-- B1 additive extension. Execute each statement in one Godot-owned write transaction.
CREATE TABLE IF NOT EXISTS world_state(campaign_id TEXT PRIMARY KEY NOT NULL,revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=0),turn_number INTEGER NOT NULL CHECK(typeof(turn_number)='integer' AND turn_number>=0),pending_turn_id TEXT,elapsed_seconds INTEGER CHECK(elapsed_seconds IS NULL OR (typeof(elapsed_seconds)='integer' AND elapsed_seconds>=0)));
CREATE TABLE IF NOT EXISTS turn_receipts(turn_id TEXT PRIMARY KEY NOT NULL,actor_id TEXT NOT NULL REFERENCES actors(id),prior_revision INTEGER NOT NULL UNIQUE CHECK(typeof(prior_revision)='integer' AND prior_revision>=0),next_revision INTEGER NOT NULL UNIQUE CHECK(next_revision=prior_revision+1),turn_number INTEGER NOT NULL UNIQUE CHECK(typeof(turn_number)='integer' AND turn_number>0),event_id INTEGER NOT NULL UNIQUE REFERENCES events(id),payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS turn_narrations(turn_id TEXT PRIMARY KEY NOT NULL REFERENCES turn_receipts(turn_id),event_id INTEGER NOT NULL UNIQUE REFERENCES events(id),revision INTEGER NOT NULL UNIQUE CHECK(typeof(revision)='integer' AND revision>0));
CREATE TABLE IF NOT EXISTS terrain_regions(id TEXT PRIMARY KEY NOT NULL,parent_id TEXT REFERENCES terrain_regions(id),name TEXT NOT NULL,kind TEXT NOT NULL,precision TEXT NOT NULL DEFAULT 'unknown' CHECK(precision IN ('unknown','provisional','approximate','surveyed')),description TEXT NOT NULL DEFAULT '',public_description TEXT NOT NULL DEFAULT '',source_event_id INTEGER REFERENCES events(id),CHECK(parent_id IS NULL OR parent_id<>id));
CREATE TABLE IF NOT EXISTS terrain_points(region_id TEXT NOT NULL REFERENCES terrain_regions(id) ON DELETE CASCADE,seq INTEGER NOT NULL CHECK(typeof(seq)='integer' AND seq BETWEEN 0 AND 255),x REAL NOT NULL CHECK(typeof(x) IN ('real','integer') AND abs(x)<=1e12),y REAL NOT NULL CHECK(typeof(y) IN ('real','integer') AND abs(y)<=1e12),PRIMARY KEY(region_id,seq));
CREATE TABLE IF NOT EXISTS world_places(location_id TEXT PRIMARY KEY NOT NULL REFERENCES locations(id),region_id TEXT REFERENCES terrain_regions(id),precision TEXT NOT NULL DEFAULT 'unknown' CHECK(precision IN ('unknown','provisional','approximate','surveyed')),uncertainty_miles REAL CHECK(uncertainty_miles IS NULL OR (typeof(uncertainty_miles) IN ('real','integer') AND uncertainty_miles>=0 AND uncertainty_miles<=1e12)),elevation_feet REAL CHECK(elevation_feet IS NULL OR (typeof(elevation_feet) IN ('real','integer') AND abs(elevation_feet)<=1e12)),terrain TEXT,footprint TEXT,population INTEGER CHECK(population IS NULL OR (typeof(population)='integer' AND population>=0)),occupancy TEXT NOT NULL DEFAULT 'unknown' CHECK(occupancy IN ('unknown','inhabited','uninhabited','abandoned')),asset_id TEXT,description TEXT NOT NULL DEFAULT '',public_description TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',source_event_id INTEGER REFERENCES events(id),CHECK((precision IN ('unknown','provisional') AND uncertainty_miles IS NULL) OR (precision IN ('approximate','surveyed') AND uncertainty_miles IS NOT NULL)));
CREATE TABLE IF NOT EXISTS location_aliases(location_id TEXT NOT NULL REFERENCES world_places(location_id),alias TEXT COLLATE NOCASE NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN ('player','private')),source_event_id INTEGER NOT NULL REFERENCES events(id),PRIMARY KEY(location_id,alias));
CREATE TABLE IF NOT EXISTS geographic_relationships(id TEXT PRIMARY KEY NOT NULL,from_id TEXT NOT NULL REFERENCES world_places(location_id),to_id TEXT NOT NULL REFERENCES world_places(location_id),kind TEXT NOT NULL,direction TEXT,distance_miles REAL CHECK(distance_miles IS NULL OR (typeof(distance_miles) IN ('real','integer') AND distance_miles>=0 AND distance_miles<=1e12)),precision TEXT NOT NULL CHECK(precision IN ('unknown','provisional','approximate','surveyed')),visibility TEXT NOT NULL CHECK(visibility IN ('player','private')),source_event_id INTEGER NOT NULL REFERENCES events(id),CHECK(from_id<>to_id),UNIQUE(from_id,to_id,kind));
CREATE TABLE IF NOT EXISTS world_routes(id TEXT PRIMARY KEY NOT NULL,from_id TEXT NOT NULL REFERENCES world_places(location_id),to_id TEXT NOT NULL REFERENCES world_places(location_id),name TEXT NOT NULL,kind TEXT NOT NULL,precision TEXT NOT NULL CHECK(precision IN ('unknown','provisional','approximate','surveyed')),distance_miles REAL CHECK(distance_miles IS NULL OR (typeof(distance_miles) IN ('real','integer') AND distance_miles>=0 AND distance_miles<=1e12)),source_event_id INTEGER NOT NULL REFERENCES events(id),CHECK(from_id<>to_id));
CREATE TABLE IF NOT EXISTS route_points(route_id TEXT NOT NULL REFERENCES world_routes(id) ON DELETE CASCADE,seq INTEGER NOT NULL CHECK(typeof(seq)='integer' AND seq BETWEEN 0 AND 255),x REAL NOT NULL CHECK(typeof(x) IN ('real','integer') AND abs(x)<=1e12),y REAL NOT NULL CHECK(typeof(y) IN ('real','integer') AND abs(y)<=1e12),PRIMARY KEY(route_id,seq));
CREATE TABLE IF NOT EXISTS world_discovery(id TEXT PRIMARY KEY NOT NULL,location_id TEXT UNIQUE REFERENCES world_places(location_id),route_id TEXT UNIQUE REFERENCES world_routes(id),region_id TEXT UNIQUE REFERENCES terrain_regions(id),status TEXT NOT NULL CHECK(status IN ('unknown','reported','observed','visited','surveyed')),visibility TEXT NOT NULL CHECK(visibility IN ('player','private')),first_event_id INTEGER REFERENCES events(id),last_visit_event_id INTEGER REFERENCES events(id),CHECK((location_id IS NOT NULL)+(route_id IS NOT NULL)+(region_id IS NOT NULL)=1),CHECK(visibility='private' OR (status<>'unknown' AND first_event_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS movement_history(turn_id TEXT NOT NULL REFERENCES turn_receipts(turn_id),seq INTEGER NOT NULL CHECK(typeof(seq)='integer' AND seq BETWEEN 0 AND 63),actor_id TEXT NOT NULL REFERENCES actors(id),from_id TEXT NOT NULL REFERENCES world_places(location_id),to_id TEXT NOT NULL REFERENCES world_places(location_id),route_id TEXT REFERENCES world_routes(id),distance_miles REAL CHECK(distance_miles IS NULL OR (typeof(distance_miles) IN ('real','integer') AND distance_miles>=0 AND distance_miles<=1e12)),elapsed_seconds INTEGER CHECK(elapsed_seconds IS NULL OR (typeof(elapsed_seconds)='integer' AND elapsed_seconds>=0)),precision TEXT NOT NULL CHECK(precision IN ('unknown','provisional','approximate','surveyed')),PRIMARY KEY(turn_id,seq),CHECK(from_id<>to_id));
CREATE TABLE IF NOT EXISTS movement_points(turn_id TEXT NOT NULL,segment_seq INTEGER NOT NULL,seq INTEGER NOT NULL CHECK(typeof(seq)='integer' AND seq BETWEEN 0 AND 255),x REAL NOT NULL CHECK(typeof(x) IN ('real','integer') AND abs(x)<=1e12),y REAL NOT NULL CHECK(typeof(y) IN ('real','integer') AND abs(y)<=1e12),PRIMARY KEY(turn_id,segment_seq,seq),FOREIGN KEY(turn_id,segment_seq) REFERENCES movement_history(turn_id,seq) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS world_annotations(id TEXT PRIMARY KEY NOT NULL,location_id TEXT NOT NULL REFERENCES world_places(location_id),actor_id TEXT NOT NULL REFERENCES actors(id),text TEXT NOT NULL CHECK(length(text) BETWEEN 1 AND 1000),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS world_links(id TEXT PRIMARY KEY NOT NULL,location_id TEXT NOT NULL REFERENCES world_places(location_id),actor_id TEXT REFERENCES actors(id),quest_id TEXT REFERENCES quests(id),encounter_id TEXT REFERENCES encounters(id),source_event_id INTEGER NOT NULL REFERENCES events(id),CHECK((actor_id IS NOT NULL)+(quest_id IS NOT NULL)+(encounter_id IS NOT NULL)=1));
CREATE TABLE IF NOT EXISTS geography_audit(id TEXT PRIMARY KEY NOT NULL,request_id TEXT NOT NULL,source_event_id INTEGER NOT NULL REFERENCES events(id),proposal_index INTEGER NOT NULL CHECK(typeof(proposal_index)='integer' AND proposal_index>=0),revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=0),status TEXT NOT NULL CHECK(status IN ('accepted','conflict','deferred','rejected')),subject_id TEXT,detail TEXT NOT NULL,UNIQUE(request_id,source_event_id,proposal_index));
CREATE INDEX IF NOT EXISTS world_places_region ON world_places(region_id);
CREATE INDEX IF NOT EXISTS world_places_precision ON world_places(precision);
CREATE INDEX IF NOT EXISTS locations_world_xy ON locations(x,y);
CREATE INDEX IF NOT EXISTS location_alias_lookup ON location_aliases(alias);
CREATE INDEX IF NOT EXISTS geo_to ON geographic_relationships(to_id);
CREATE INDEX IF NOT EXISTS routes_from ON world_routes(from_id);
CREATE INDEX IF NOT EXISTS routes_to ON world_routes(to_id);
CREATE INDEX IF NOT EXISTS movement_actor ON movement_history(actor_id,turn_id,seq);
CREATE INDEX IF NOT EXISTS discovery_visibility ON world_discovery(visibility,status);
CREATE INDEX IF NOT EXISTS links_location ON world_links(location_id);
CREATE INDEX IF NOT EXISTS audit_source ON geography_audit(source_event_id);
